document.querySelectorAll('[data-copy]').forEach(function(el){
  el.addEventListener('click',function(){
    var txt=el.getAttribute('data-copy'), toast=document.getElementById('toast');
    function show(m){toast.textContent=m;toast.classList.add('show');setTimeout(function(){toast.classList.remove('show')},1800);}
    try{
      navigator.clipboard.writeText(txt).then(function(){show('복사했어요');},function(){show('길게 눌러 직접 복사해 주세요');});
    }catch(e){show('길게 눌러 직접 복사해 주세요');}
  });
});
